"""Integration tests for ``justorm.oracledb``.

These tests require a running Oracle instance and the
``python-oracledb`` package.  Both are opt-in: set
``JUSTORM_ORACLE_DSN`` and install the ``oracledb`` extra.

Oracle is where justorm's dialect-specific surface matters most:

* identifiers are quoted with double quotes (Oracle folds unquoted
  identifiers to upper case, so justorm always quotes and the tests
  create their tables with quoted names),
* placeholders are **named** (``:p<hex>``), generated by the builder;
  parameters are passed to the driver as a dict,
* ``RETURNING`` requires an OUT bind variable and is not modelled,
* upserts use ``MERGE``, which justorm does not model,
* ``DISTINCT ON`` and ``ILIKE`` are not available,
* ``FOR UPDATE`` is supported, with ``NOWAIT`` / ``SKIP LOCKED``,
* ``LIMIT`` / ``OFFSET`` map to ``OFFSET ... ROWS FETCH NEXT ...
  ROWS ONLY`` (12c+); no ``ORDER BY`` is required,
* ``DEFAULT`` is not accepted inside a ``VALUES`` list.

The shared builder logic is exercised in ``test_builder.py``; here we
check that Oracle accepts the SQL justorm generates, and that the
things Oracle does not have are rejected before they reach the server.
"""

from __future__ import annotations

from collections import namedtuple

import pytest

oracledb = pytest.importorskip("oracledb")

import justorm.oracledb
from justorm import JustormDialectError, JustormError


pytestmark = pytest.mark.oracledb


# ---------------------------------------------------------------------------
# Cursor creation
#
# ``oracledb.Connection.cursor()`` returns the driver's own cursor and
# does not accept a replacement class, so the justorm cursor is
# constructed directly from the connection.
# ---------------------------------------------------------------------------


def _cursor(conn):
    return justorm.oracledb.Cursor(conn)


# ---------------------------------------------------------------------------
# Cursor identity and native surface
# ---------------------------------------------------------------------------


class TestCursorIdentity:
    def test_cursor_is_oracledb_cursor(self, oracle_conn):
        cur = _cursor(oracle_conn)
        try:
            assert isinstance(cur, oracledb.Cursor)
        finally:
            cur.close()

    def test_dialect_name(self, oracle_conn):
        cur = _cursor(oracle_conn)
        try:
            assert cur.dialect_name == "oracledb"
        finally:
            cur.close()

    def test_native_execute_returns_cursor(self, oracle_conn):
        cur = _cursor(oracle_conn)
        try:
            # python-oracledb's ``execute`` returns the cursor, so the
            # justorm wrapper does too.
            result = cur.execute("SELECT 1 FROM DUAL")
            assert result is cur
            assert cur.fetchone() == (1,)
        finally:
            cur.close()

    def test_table_named_like_a_cursor_attribute(self, oracle_conn):
        cur = _cursor(oracle_conn)
        try:
            assert callable(cur.execute)
            assert cur.table("execute") is not None
        finally:
            cur.close()


# ---------------------------------------------------------------------------
# Fixtures
# ---------------------------------------------------------------------------


@pytest.fixture()
def users_table(oracle_conn):
    """A small ``users`` table with a unique ``name`` column.

    All identifiers are quoted, so the table is created with the exact
    lower-case name justorm will produce when it renders
    ``cur.table("users")``.
    """
    cur = _cursor(oracle_conn)
    try:
        cur.execute(
            """
            CREATE TABLE "users" (
                "id"     NUMBER GENERATED BY DEFAULT AS IDENTITY
                         PRIMARY KEY,
                "name"   VARCHAR2(64) NOT NULL,
                "age"    NUMBER,
                "active" NUMBER(1) DEFAULT 1 NOT NULL,
                CONSTRAINT "uq_users_name" UNIQUE ("name")
            )
            """
        )
        cur.table("users").insert(
            [
                {"name": "Alice", "age": 30, "active": 1},
                {"name": "Bob", "age": 25, "active": 1},
                {"name": "Carol", "age": 40, "active": 0},
            ]
        )
    finally:
        cur.close()
    return "users"


# ---------------------------------------------------------------------------
# fetch* with format=
# ---------------------------------------------------------------------------


class TestFetchFormat:
    def test_fetchone_default(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            cur.execute('SELECT "id", "name" FROM "users" ORDER BY "id"')
            row = cur.fetchone()
            assert isinstance(row, tuple)
            assert row[1] == "Alice"
        finally:
            cur.close()

    def test_fetchone_dict(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            cur.execute('SELECT "id", "name" FROM "users" ORDER BY "id"')
            row = cur.fetchone(format=dict)
            assert row == {"id": 1, "name": "Alice"}
        finally:
            cur.close()

    def test_fetchone_namedtuple(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            cur.execute('SELECT "id", "name" FROM "users" ORDER BY "id"')
            row = cur.fetchone(format=namedtuple)
            assert row.id == 1
            assert row.name == "Alice"
        finally:
            cur.close()

    def test_fetchone_none_with_format(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            cur.execute('SELECT "id" FROM "users" WHERE 1 = 0')
            assert cur.fetchone(format=dict) is None
            assert cur.fetchone(format=namedtuple) is None
        finally:
            cur.close()

    def test_fetchmany_dict(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            cur.execute('SELECT "id", "name" FROM "users" ORDER BY "id"')
            rows = cur.fetchmany(2, format=dict)
            assert rows == [
                {"id": 1, "name": "Alice"},
                {"id": 2, "name": "Bob"},
            ]
        finally:
            cur.close()

    def test_fetchall_namedtuple(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            cur.execute('SELECT "id", "name" FROM "users" ORDER BY "id"')
            rows = cur.fetchall(format=namedtuple)
            assert rows[2].name == "Carol"
        finally:
            cur.close()

    def test_bad_format_rejected(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            cur.execute('SELECT "id" FROM "users"')
            with pytest.raises(JustormError):
                cur.fetchall(format=list)
        finally:
            cur.close()


