class TestGet:
    def test_get_row(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            row = cur.table("users").where(name="Alice").get()
            assert row == {
                "id": 1,
                "name": "Alice",
                "age": 30,
                "active": 1,
            }
        finally:
            cur.close()

    def test_get_missing_returns_none(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            assert cur.table("users").where(name="Nobody").get() is None
        finally:
            cur.close()

    def test_get_default(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            assert cur.table("users").where(name="Nobody").get(default={}) == {}
        finally:
            cur.close()

    def test_get_scalar(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            assert cur.table("users").where(name="Alice").get("name") == "Alice"
        finally:
            cur.close()

    def test_get_tuple(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            row = cur.table("users").where(name="Alice").get(("id", "name"))
            assert row == (1, "Alice")
        finally:
            cur.close()

    def test_get_rejects_key(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            with pytest.raises(JustormError):
                cur.table("users").where(name="Alice").get(key="id")
        finally:
            cur.close()


# ---------------------------------------------------------------------------
# query
# ---------------------------------------------------------------------------


class TestQuery:
    def test_query_select_returns_dicts(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            rows = cur.query(
                'SELECT "id", "name" FROM "users" ORDER BY "id"'
            )
            assert rows == [
                {"id": 1, "name": "Alice"},
                {"id": 2, "name": "Bob"},
                {"id": 3, "name": "Carol"},
            ]
        finally:
            cur.close()

    def test_query_select_with_params(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            rows = cur.query(
                'SELECT "name" FROM "users" '
                'WHERE "age" > :p1 ORDER BY "id"',
                {"p1": 26},
            )
            assert rows == [{"name": "Alice"}, {"name": "Carol"}]
        finally:
            cur.close()

    def test_query_select_empty(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            assert (
                cur.query('SELECT "id" FROM "users" WHERE 1 = 0')
                == []
            )
        finally:
            cur.close()

    def test_query_insert_returns_rowcount(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            result = cur.query(
                'INSERT INTO "users" ("name", "age") '
                "VALUES (:p1, :p2)",
                {"p1": "Dave", "p2": 50},
            )
            # python-oracledb exposes ``lastrowid`` as a rowid string,
            # not an int, so ``query`` falls back to rowcount for
            # INSERT statements.
            assert result == 1
        finally:
            cur.close()

    def test_query_update_returns_rowcount(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            result = cur.query(
                'UPDATE "users" SET "age" = :p1 WHERE "age" > :p2',
                {"p1": 99, "p2": 28},
            )
            assert result == 2
        finally:
            cur.close()

    def test_query_delete_returns_rowcount(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            result = cur.query(
                'DELETE FROM "users" WHERE "name" = :p1',
                {"p1": "Bob"},
            )
            assert result == 1
        finally:
            cur.close()

    def test_query_ddl_returns_int(self, oracle_conn):
        cur = _cursor(oracle_conn)
        try:
            result = cur.query('CREATE TABLE "t" ("id" NUMBER)')
            assert isinstance(result, int)
        finally:
            cur.close()

    def test_query_bad_sql_raises(self, oracle_conn):
        cur = _cursor(oracle_conn)
        try:
            with pytest.raises(oracledb.Error):
                cur.query('SELECT * FROM "no_such_table"')
        finally:
            cur.close()


# ---------------------------------------------------------------------------
# SELECT
# ---------------------------------------------------------------------------


class TestSelect:
    def test_select_all(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            rows = cur.table("users").orderby("id").select()
            assert len(rows) == 3
            assert {r["name"] for r in rows} == {"Alice", "Bob", "Carol"}
        finally:
            cur.close()

    def test_identifier_quoting_uses_double_quotes(self, oracle_conn):
        cur = _cursor(oracle_conn)
        try:
            # Reserved words as quoted identifiers must round-trip.
            cur.execute(
                'CREATE TABLE "select" ("where" NUMBER, "order" NUMBER)'
            )
            cur.table("select").append(**{"where": 1, "order": 2})
            rows = cur.table("select").select()
            assert rows == [{"where": 1, "order": 2}]
        finally:
            cur.close()

    def test_where_kwargs(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            rows = cur.table("users").where(name="Alice").select()
            assert len(rows) == 1
            assert rows[0]["age"] == 30
        finally:
            cur.close()

    def test_select_scalar(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            names = cur.table("users").orderby("id").select("name")
            assert names == ["Alice", "Bob", "Carol"]
        finally:
            cur.close()

    def test_select_tuple(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            rows = (
                cur.table("users")
                .orderby("id")
                .select(("id", "name"))
            )
            assert all(isinstance(r, tuple) for r in rows)
            assert rows[0][1] == "Alice"
        finally:
            cur.close()

    def test_select_keyed(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            mapping = cur.table("users").select("name", key="id")
            assert set(mapping.values()) == {"Alice", "Bob", "Carol"}
        finally:
            cur.close()

    def test_limit_and_offset(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            rows = (
                cur.table("users")
                .orderby("id")
                .limit(2)
                .offset(1)
                .select("name")
            )
            assert rows == ["Bob", "Carol"]
        finally:
            cur.close()

    def test_limit_without_offset(self, oracle_conn, users_table):
        # Oracle's ``FETCH NEXT`` does not require an ORDER BY.
        cur = _cursor(oracle_conn)
        try:
            rows = cur.table("users").limit(2).select("name")
            assert len(rows) == 2
        finally:
            cur.close()

    def test_parameter_is_not_inlined(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            rows = (
                cur.table("users")
                .where(name="x'; DROP TABLE users; --")
                .select()
            )
            assert rows == []
            assert cur.table("users").select() is not None
        finally:
            cur.close()


# ---------------------------------------------------------------------------
# INSERT
# ---------------------------------------------------------------------------


class TestInsert:
    def test_append(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            assert (
                cur.table("users").append(name="Dave", age=50) is None
            )
            assert (
                len(cur.table("users").where(name="Dave").select()) == 1
            )
        finally:
            cur.close()

    def test_insert_many_rows(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            cur.table("users").insert([
                {"name": "G", "age": 1},
                {"name": "H", "age": 2},
                {"name": "I", "age": 3},
            ])
            assert (
                len(
                    cur.table("users")
                    .where_in(name=["G", "H", "I"])
                    .select()
                )
                == 3
            )
        finally:
            cur.close()

    def test_insert_missing_key_uses_null(self, oracle_conn):
        # Oracle does not accept ``DEFAULT`` inside a VALUES list, so
        # justorm substitutes NULL on that dialect.
        cur = _cursor(oracle_conn)
        try:
            cur.execute(
                'CREATE TABLE "t" ('
                '  "id" NUMBER GENERATED BY DEFAULT AS IDENTITY '
                '       PRIMARY KEY, '
                '  "a" NUMBER, '
                '  "b" NUMBER DEFAULT 99'
                ")"
            )
            cur.table("t").insert([{"a": 1, "b": 2}, {"a": 3}])
            rows = cur.table("t").orderby("a").select()
            assert rows[0]["b"] == 2
            # Oracle does not accept DEFAULT inside a VALUES list, so
            # justorm substitutes NULL: the column's own DEFAULT 99 is
            # never triggered.
            assert rows[1]["b"] is None
        finally:
            cur.close()

    def test_insert_many(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            cur.table("users").insert_many(
                [{"name": "J", "age": 1}, {"name": "K", "age": 2}],
                columns=["name", "age"],
            )
            assert (
                len(
                    cur.table("users")
                    .where_in(name=["J", "K"])
                    .select()
                )
                == 2
            )
        finally:
            cur.close()


