class TestUpdateDelete:
    def test_update(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            cur.table("users").where(name="Alice").update(age=31)
            assert (
                cur.table("users").where(name="Alice").select()[0]["age"]
                == 31
            )
        finally:
            cur.close()

    def test_update_without_where_rejected(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            with pytest.raises(JustormError):
                cur.table("users").update(age=0)
        finally:
            cur.close()

    def test_delete(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            cur.table("users").where(name="Bob").delete()
            assert cur.table("users").where(name="Bob").select() == []
        finally:
            cur.close()

    def test_delete_without_where_rejected(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            with pytest.raises(JustormError):
                cur.table("users").delete()
        finally:
            cur.close()


# ---------------------------------------------------------------------------
# RETURNING is rejected
# ---------------------------------------------------------------------------


class TestReturningRejected:
    def test_append_returning_rejected(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            with pytest.raises(JustormDialectError):
                cur.table("users").returning("id").append(
                    name="X", age=1
                )
        finally:
            cur.close()

    def test_update_returning_rejected(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            with pytest.raises(JustormDialectError):
                cur.table("users").where(name="Alice").returning("id").update(
                    age=1
                )
        finally:
            cur.close()

    def test_delete_returning_rejected(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            with pytest.raises(JustormDialectError):
                cur.table("users").where(name="Alice").returning("id").delete()
        finally:
            cur.close()

    def test_returning_into_workaround(self, oracle_conn, users_table):
        # The documented workaround on Oracle: RETURNING ... INTO
        # with an OUT bind variable, written as raw SQL.
        cur = _cursor(oracle_conn)
        try:
            var = cur.var(oracledb.NUMBER)
            cur.execute(
                'INSERT INTO "users" ("name", "age") '
                "VALUES (:p1, :p2) RETURNING \"id\" INTO :p3",
                {"p1": "Zed", "p2": 1, "p3": var},
            )
            assert var.getvalue() == [4]
        finally:
            cur.close()


# ---------------------------------------------------------------------------
# UPSERT is rejected
# ---------------------------------------------------------------------------


class TestUpsertRejected:
    def test_on_conflict_rejected(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            with pytest.raises(JustormDialectError):
                cur.table("users").on_conflict(
                    do=cur.sql.nothing()
                ).append(name="X", age=1)
        finally:
            cur.close()

    def test_on_duplicate_rejected(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            with pytest.raises(JustormDialectError):
                cur.table("users").on_duplicate(
                    update={"age": 1}
                ).append(name="X", age=1)
        finally:
            cur.close()


# ---------------------------------------------------------------------------
# Dialect-specific features
# ---------------------------------------------------------------------------


class TestDialectSpecific:
    def test_ilike_rejected(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            with pytest.raises(JustormDialectError):
                cur.table("users").where_ilike(name="alice").select()
        finally:
            cur.close()

    def test_distinct_on_rejected(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            with pytest.raises(JustormDialectError):
                cur.table("users").distinct_on("name").select()
        finally:
            cur.close()

    def test_for_update_supported(self, oracle_conn, users_table):
        # Oracle supports FOR UPDATE (no FOR SHARE, though -- the
        # renderer maps ``share=True`` to FOR UPDATE).
        cur = _cursor(oracle_conn)
        try:
            rows = (
                cur.table("users")
                .where(name="Alice")
                .select(for_update=True)
            )
            assert len(rows) == 1
        finally:
            cur.close()

    def test_distinct_works(self, oracle_conn):
        cur = _cursor(oracle_conn)
        try:
            cur.execute('CREATE TABLE "t" ("a" NUMBER)')
            cur.table("t").insert([{"a": 1}, {"a": 1}, {"a": 2}])
            rows = cur.table("t").distinct().orderby("a").select("a")
            assert rows == [1, 2]
        finally:
            cur.close()


# ---------------------------------------------------------------------------
# Subquery
# ---------------------------------------------------------------------------


class TestSubquery:
    def test_subquery_join(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            cur.execute(
                'CREATE TABLE "orders" ('
                '  "id"      NUMBER GENERATED BY DEFAULT AS IDENTITY '
                '            PRIMARY KEY, '
                '  "user_id" NUMBER NOT NULL, '
                '  "total"   NUMBER NOT NULL'
                ")"
            )
            cur.table("orders").insert(
                [
                    {"user_id": 1, "total": 50},
                    {"user_id": 1, "total": 200},
                    {"user_id": 2, "total": 10},
                ]
            )

            users = cur.table("users")
            orders = cur.table("orders")

            sub = orders.where(
                orders["total"] > 100
            ).select_subquery({"user_id"})
            s = sub.as_("s")

            rows = users.join(
                s, on=users["id"] == s["user_id"]
            ).select({users["name"]})
            assert [r["name"] for r in rows] == ["Alice"]
        finally:
            cur.close()


# ---------------------------------------------------------------------------
# Nested subqueries
# ---------------------------------------------------------------------------


class TestNestedSubquery:
    @pytest.fixture()
    def three_tables(self, oracle_conn):
        cur = _cursor(oracle_conn)
        try:
            cur.execute(
                'CREATE TABLE "users" ('
                '  "id"   NUMBER GENERATED BY DEFAULT AS IDENTITY '
                '         PRIMARY KEY, '
                '  "name" VARCHAR2(64) NOT NULL'
                ")"
            )
            cur.execute(
                'CREATE TABLE "orders" ('
                '  "id"      NUMBER GENERATED BY DEFAULT AS IDENTITY '
                '            PRIMARY KEY, '
                '  "user_id" NUMBER NOT NULL, '
                '  "total"   NUMBER NOT NULL'
                ")"
            )
            cur.execute(
                'CREATE TABLE "order_items" ('
                '  "id"       NUMBER GENERATED BY DEFAULT AS IDENTITY '
                '             PRIMARY KEY, '
                '  "order_id" NUMBER NOT NULL, '
                '  "qty"      NUMBER NOT NULL'
                ")"
            )
            cur.table("users").insert([
                {"name": "Alice"},
                {"name": "Bob"},
            ])
            cur.table("orders").insert([
                {"user_id": 1, "total": 50},
                {"user_id": 1, "total": 200},
                {"user_id": 2, "total": 10},
            ])
            cur.table("order_items").insert([
                {"order_id": 2, "qty": 3},
                {"order_id": 2, "qty": 4},
                {"order_id": 3, "qty": 1},
            ])
        finally:
            cur.close()
        return "users"

    def test_two_subqueries_joined(self, oracle_conn, three_tables):
        cur = _cursor(oracle_conn)
        try:
            users = cur.table("users")
            orders = cur.table("orders")
            items = cur.table("order_items")

            big_orders = orders.where(
                orders["total"] > 100
            ).select_subquery({"id", "user_id"})
            item_ids = items.where(
                items["qty"] > 2
            ).select_subquery({"order_id"})
            bo = big_orders.as_("bo")
            it = item_ids.as_("it")

            rows = users.join(
                bo, on=users["id"] == bo["user_id"]
            ).join(
                it, on=bo["id"] == it["order_id"]
            ).select({users["name"]})
            # Two order_items rows match the same big order, so Alice
            # appears twice.
            assert [r["name"] for r in rows] == ["Alice", "Alice"]
        finally:
            cur.close()

    def test_subquery_with_join_inside(self, oracle_conn, three_tables):
        cur = _cursor(oracle_conn)
        try:
            users = cur.table("users")
            orders = cur.table("orders")

            inner = users.join(
                orders,
                on=users["id"] == orders["user_id"],
            ).where(
                orders["total"] > 100
            ).select_subquery({users["id"]})
            s = inner.as_("s")

            rows = s.select()
            assert [r["id"] for r in rows] == [1]
        finally:
            cur.close()

    def test_subquery_with_group_style_filter(self, oracle_conn, three_tables):
        cur = _cursor(oracle_conn)
        try:
            users = cur.table("users")
            orders = cur.table("orders")

            big = orders.where(
                orders["total"] > 100
            ).select_subquery({"user_id"})
            s = big.as_("s")

            rows = users.join(
                s, on=users["id"] == s["user_id"]
            ).select({users["name"]})
            assert [r["name"] for r in rows] == ["Alice"]
        finally:
            cur.close()


# ---------------------------------------------------------------------------
# Errors from the server
# ---------------------------------------------------------------------------


class TestServerErrors:
    def test_missing_table(self, oracle_conn):
        cur = _cursor(oracle_conn)
        try:
            with pytest.raises(oracledb.Error):
                cur.table("no_such_table").select()
        finally:
            cur.close()

    def test_missing_column(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            with pytest.raises(oracledb.Error):
                cur.table("users").where(no_such_column=1).select()
        finally:
            cur.close()


# ---------------------------------------------------------------------------
# Transactions
# ---------------------------------------------------------------------------


class TestTransactions:
    def test_rollback_discards_insert(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            # The fixture runs with autocommit on, so to test rollback
            # we explicitly disable it for the duration of the test.
            oracle_conn.autocommit = False
            cur.table("users").append(name="Temp", age=1)
            oracle_conn.rollback()
            assert cur.table("users").where(name="Temp").select() == []
        finally:
            oracle_conn.autocommit = True
            cur.close()

    def test_commit_persists_insert(self, oracle_conn, users_table):
        cur = _cursor(oracle_conn)
        try:
            oracle_conn.autocommit = False
            cur.table("users").append(name="Persist", age=1)
            oracle_conn.commit()
            assert (
                len(cur.table("users").where(name="Persist").select()) == 1
            )
        finally:
            oracle_conn.autocommit = True
            cur.close()